/* ── Primitives ─────────────────────────────────────────── */
function Rule() {
  return <div style={{ borderTop:`1px solid #2a2a2a`, margin:"40px 0" }} />;
}
function PartTag({ children }) {
  return (
    <span style={{ display:"inline-block", border:"1px solid #2a2a2a", color:"#666", fontSize:11,
      fontFamily:"'DM Mono',monospace", letterSpacing:"0.14em", padding:"2px 10px", borderRadius:3, marginBottom:14 }}>
      {children}
    </span>
  );
}
function SectionHeading({ en, zh }) {
  return (
    <div style={{ marginBottom:32 }}>
      <h2 style={{ fontFamily:"'Barlow Condensed',sans-serif", fontSize:"clamp(28px,4.5vw,42px)",
        fontWeight:800, color:C.teal, textTransform:"uppercase", letterSpacing:"0.03em", lineHeight:1.05, margin:0 }}>
        {en}
      </h2>
      <div style={{ fontFamily:"'DM Sans','Noto Sans TC',sans-serif", fontSize:17, color:C.textZh, marginTop:6 }}>{zh}</div>
    </div>
  );
}
function SubLabel({ en, zh }) {
  return (
    <div style={{ fontFamily:"'Barlow Condensed',sans-serif", fontSize:16, fontWeight:700,
      color:C.textHi, textTransform:"uppercase", letterSpacing:"0.1em",
      borderBottom:"1px solid #2a2a2a", paddingBottom:8, marginBottom:20,
      display:"flex", gap:14, alignItems:"baseline" }}>
      <span>{en}</span>
      {zh && <span style={{ fontFamily:"'DM Sans','Noto Sans TC',sans-serif", fontWeight:400, fontSize:14,
        color:C.textZh, letterSpacing:0, textTransform:"none" }}>{zh}</span>}
    </div>
  );
}
function Card({ children, accentLeft, style={} }) {
  return (
    <div style={{ background:C.surf, border:`1px solid ${C.border}`,
      borderLeft: accentLeft ? `3px solid ${accentLeft}` : `1px solid ${C.border}`,
      borderRadius:6, padding:"22px 24px", marginBottom:14, position:"relative", ...style }}>
      {children}
    </div>
  );
}
function StepCircle({ n, color=C.orange }) {
  return (
    <div style={{ minWidth:34, height:34, borderRadius:"50%", background:"transparent",
      border:`2px solid ${color}`, display:"flex", alignItems:"center", justifyContent:"center",
      color, fontSize:15, fontWeight:700, fontFamily:"'DM Mono',monospace", flexShrink:0 }}>
      {n}
    </div>
  );
}
function StepRow({ num, en, zh, accentColor }) {
  return (
    <div style={{ display:"flex", gap:16, alignItems:"flex-start", padding:"14px 0", borderBottom:"1px solid #1e1e1e" }}>
      <StepCircle n={num} color={accentColor||C.orange} />
      <div>
        <div style={{ fontSize:16, color:C.textMed, lineHeight:1.65 }}>{en}</div>
        <div style={{ fontSize:15, color:C.textZh, marginTop:5, fontFamily:"'DM Sans','Noto Sans TC',sans-serif", lineHeight:1.65 }}>{zh}</div>
      </div>
    </div>
  );
}
function CodeBox({ children }) {
  return (
    <div style={{ background:C.surf2, border:"1px solid #2a2a2a", borderRadius:5,
      padding:"13px 18px", fontFamily:"'DM Mono',monospace", fontSize:13,
      color:C.textMed, lineHeight:1.7, margin:"12px 0" }}>
      {children}
    </div>
  );
}
/* Real screenshot — with border + label overlay */
function Screenshot({ src, alt, label }) {
  return (
    <div style={{ margin:"10px 0" }}>
      <img src={src} alt={alt}
        style={{ width:"100%", display:"block", borderRadius:6,
          border:"1px solid #2a2a2a", objectFit:"contain" }} />
      {label && (
        <div style={{ fontFamily:"'DM Mono',monospace", fontSize:10, color:"#555",
          textAlign:"center", marginTop:6, letterSpacing:"0.08em" }}>
          {label}
        </div>
      )}
    </div>
  );
}

